'use strict';
let DATA, FOUNDATIONS;
const STORE_KEY = 'mmj-html-offline-v1';
const MAIN_TABS = [['overview','Overview'],['sessions','Sessions & materials'],['primer','Participant primer'],['tracker','Law tracker'],['assignments','Assignment drafts'],['library','Downloads'],['about','Course information']];
const state = {view:'overview',session:null,day:'all',search:'',primer:'foundations',glossary:'',region:'Global',lawType:'Legislation',lawSearch:''};
let saved = {progress:[],assignments:[]}, persistence = true, toastTimer, editId = null;
try { const raw = localStorage.getItem(STORE_KEY); if (raw) { const value=JSON.parse(raw); if (Array.isArray(value.progress)) saved.progress=value.progress.filter(n=>Number.isInteger(n)&&n>=1&&n<=14); if (Array.isArray(value.assignments)) saved.assignments=value.assignments.filter(a=>a&&typeof a.id==='string'&&typeof a.title==='string'); } } catch { persistence=false; }
function escapeHTML(value) { return String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])); }
const e=escapeHTML;
function safeURL(value) { try { const url=new URL(value); return url.protocol==='https:'?url.href:'#'; } catch { return '#'; } }
function external(url,label,cls='') {return `<a class="${e(cls)}" href="${e(safeURL(url))}" target="_blank" rel="noopener noreferrer">${e(label)} ↗</a>`;}
function date(value) {return new Date(value+'T00:00:00+05:30').toLocaleDateString('en-GB',{day:'numeric',month:'long',year:'numeric',timeZone:'Asia/Kolkata'});}
function time(value) {const [h,m]=value.split(':').map(Number);return `${h%12||12}:${String(m).padStart(2,'0')} ${h>=12?'PM':'AM'}`;}
function button(action,label,extra='',cls='button secondary') {return `<button class="${cls}" data-action="${action}" ${extra}>${label}</button>`;}
function heading(kicker,title,description='',action='') {return `<div class="page-heading"><div><span class="overline">${e(kicker)}</span><h1>${e(title)}</h1>${description?`<p>${e(description)}</p>`:''}</div>${action}</div>`;}
function paragraphs(items) {return items.map(t=>`<p>${e(t)}</p>`).join('');}
function list(items,ordered=false) {const tag=ordered?'ol':'ul';return `<${tag}>${items.map(t=>`<li>${e(t)}</li>`).join('')}</${tag}>`;}
function notice(message) {const el=document.getElementById('toast');el.textContent=message;clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.textContent='',6500);}
function persist() {try{localStorage.setItem(STORE_KEY,JSON.stringify(saved));persistence=true;return true;}catch{persistence=false;notice('Browser storage is unavailable. Changes remain in this tab only. Export your drafts before closing.');return false;}}
function download0(filename,content,type='text/plain;charset=utf-8') {const blob=content instanceof Blob?content:new Blob([content],{type});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500);}
function downloadPDF(key) {location.href='/api/asset/'+encodeURIComponent(key);}
function calendar(sessions=DATA.sessions) {const esc=s=>s.replaceAll('\\','\\\\').replaceAll('\n','\\n').replaceAll(',','\\,').replaceAll(';','\\;');const stamp=(s,t)=>new Date(s.date+'T'+t+':00+05:30').toISOString().replaceAll('-','').replaceAll(':','').replace('.000','');const lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Mind Machine Justice//Course//EN','CALSCALE:GREGORIAN',...sessions.flatMap(s=>['BEGIN:VEVENT','UID:mmj2026-session-'+s.n+'@nfsu-course','DTSTAMP:20261102T000000Z','DTSTART:'+stamp(s,s.start),'DTEND:'+stamp(s,s.end),'SUMMARY:'+esc(s.title),'DESCRIPTION:Online session. Joining link supplied separately by the organisers. Schedule may change.','END:VEVENT']),'END:VCALENDAR'];download('Mind-Machine-Justice-2026.ics',lines.join('\r\n'),'text/calendar');}
function go(view,session=null) {state.view=view;state.session=session;location.hash=session?'session-'+session:view;document.getElementById('sidebar').classList.remove('show');document.getElementById('menu').setAttribute('aria-expanded','false');render();window.scrollTo(0,0);document.getElementById('main').focus({preventScroll:true});}
function readHash() {const hash=location.hash.slice(1);const match=/^session-(\d+)$/.exec(hash);if(match&&DATA.sessions.some(s=>s.n===Number(match[1]))){state.view='sessions';state.session=Number(match[1]);}else if(allTabs().some(t=>t[0]===hash)){state.view=hash;state.session=null;}render();}
function sessionCard(s) {return `<button class="card card-button session-card" data-action="session" data-id="${s.n}"><div class="session-meta"><span class="number">${String(s.n).padStart(2,'0')}</span><span>${s.date.slice(-2)} NOVEMBER</span><span>${saved.progress.includes(s.n)?'PREPARED':''}</span></div><span class="theme">${e(s.theme)}</span><h3>${e(s.title)}</h3><div class="session-footer"><span>${time(s.start)} – ${time(s.end)} IST</span><span>↗</span></div></button>`;}
function overview() {return `${heading('SECOND EDITION · 16–22 NOVEMBER 2026','Your next frontier in law begins here.','',button('calendar','Add course to calendar'))}<section class="hero"><div><span class="pill">SECOND EDITION · ONLINE CERTIFICATE COURSE</span><h2>Mind, Machine<br>&amp; Justice.</h2><p class="subtitle">Legal Implications of Neurotechnology</p><p class="hero-desc">Explore the science. Question the inference.<br>Shape responsible governance.</p><div class="inline-meta"><span>16–22 November 2026</span><span>14 contact hours</span></div>${button('navigate','Explore the sessions →','data-view="sessions"','button')}</div><div class="art" aria-hidden="true"><svg viewBox="0 0 240 240" fill="none" stroke="currentColor" stroke-width="2"><path d="M120 40c-24-18-49-4-50 17-27-2-43 29-28 49-23 13-22 48 0 60-5 25 26 44 44 33 8 17 27 18 34 3V40Zm0 0c24-18 49-4 50 17 27-2 43 29 28 49 23 13 22 48 0 60 5 25-26 44-44 33-8 17-27 18-34 3V40Z"/><path d="M70 57c-5 20 11 30 27 23m-55 26c15-8 29-3 33 12m-33 48c14 6 29 2 36-13m8 46c16-10 17-23 7-35M170 57c5 20-11 30-27 23m55 26c-15-8-29-3-33 12m33 48c-14 6-29 2-36-13m-8 46c-16-10-17-23-7-35M120 104H95v29H69m51-3h24v20h27"/><circle cx="95" cy="104" r="4"/><circle cx="69" cy="133" r="4"/><circle cx="171" cy="150" r="4"/></svg><div class="art-label">SCIENCE · RIGHTS · JUSTICE</div></div></section><div class="stats">${[[14,'curated sessions'],[FOUNDATIONS.glossary.length,'key concepts'],[DATA.laws.length,'legal references'],[saved.progress.length,'modules prepared']].map(([n,label],i)=>`<div class="stat"><span>0${i+1} / ${['LEARN','UNDERSTAND','CONNECT','PREPARE'][i]}</span><strong>${n}<small>${label}</small></strong></div>`).join('')}</div><div class="section-heading"><div><span class="overline">A CLEAR PATH THROUGH THE COURSE</span><h2>Your learning journey</h2></div></div><div class="grid three">${[['primer','01','Build your foundation','Start with core concepts, a selective history and a searchable glossary.'],['sessions','02','Prepare for each session','Read learning goals, questions, reading guides and original practice tasks.'],['tracker','03','Follow the legal landscape','Compare Indian and global legislation, decisions and policy frameworks.']].map(([view,n,title,description])=>`<button class="card card-button" data-action="navigate" data-view="${view}"><span class="number">${n}</span><h3>${title}</h3><p>${description}</p><span class="text-link">Explore →</span></button>`).join('')}</div><div class="section-heading"><h2>Opening day</h2>${button('navigate','Full schedule →','data-view="sessions"','text-link')}</div><div class="grid two">${DATA.sessions.slice(0,2).map(sessionCard).join('')}</div>`;}
function sessions() {const s=DATA.sessions.find(x=>x.n===state.session);if(s)return sessionDetail(s);return `${heading('SEVEN DAYS · FOURTEEN PERSPECTIVES','Sessions & materials','One place for preparation, readings and original learning resources.',button('calendar','Download calendar'))}<div class="info">${e(DATA.course.notice)}</div><div class="toolbar"><div class="chips">${['all',...Array.from({length:7},(_,i)=>'2026-11-'+(16+i))].map(d=>`<button data-action="day" data-value="${d}" aria-pressed="${state.day===d}">${d==='all'?'All days':d.slice(-2)+' Nov'}</button>`).join('')}</div><input class="search" type="search" data-filter="search" aria-label="Find a session or topic" placeholder="Find a session or topic" value="${e(state.search)}"></div><div id="session-results" class="grid two">${sessionResults()}</div>`;}
function sessionResults(){const rows=DATA.sessions.filter(s=>(state.day==='all'||s.date===state.day)&&[s.title,s.theme,...s.keywords].join(' ').toLowerCase().includes(state.search.toLowerCase()));return rows.length?rows.map(sessionCard).join(''):'<div class="empty">No matching sessions. Try another topic or choose all days.</div>';}
function sessionDetailBase(s) {return `${button('navigate','← All sessions','data-view="sessions"','back')}${heading('SESSION '+String(s.n).padStart(2,'0')+' · '+s.theme,s.title)}<div class="inline-meta"><span>${date(s.date)}</span><span>${time(s.start)} – ${time(s.end)} IST</span></div><div class="detail-grid"><div class="stack"><section class="panel prose"><span class="pill">ORIGINAL PREPARATORY MODULE</span><h2 style="margin-top:20px">Before the conversation</h2><p>${e(s.overview)}</p><h3>What you will examine</h3>${list(s.objectives)}<h3>Questions to bring</h3>${list(s.questions,true)}<p class="fine">An independently prepared study guide, not a transcript or a statement of the speaker’s views.</p></section><section class="case-card prose"><span class="overline">APPLY THE CONCEPT</span><h2>A question for practice</h2><p>${e(s.scenario)}</p><div class="practice"><strong>Try this</strong><p>${e(s.activity)}</p></div><p class="fine">Preparatory exercise only; assessed tasks are notified separately by the organisers.</p></section><section class="panel"><h2>Session resources</h2><p class="muted">Participant primer and course brochure for enrolled participants.</p>${dlButtons()}</section></div><aside class="stack detail-aside"><section class="panel"><h3>Your preparation</h3><p class="muted">Read the guide and note one question for discussion.</p>${button('prepared',saved.progress.includes(s.n)?'✓ Prepared':'Mark as prepared',`data-id="${s.n}"`,'button full')}<p class="fine" style="margin-top:12px">Stored locally in this browser, not an attendance record.</p>${button('calendar-one','Add session to calendar',`data-id="${s.n}"`,'text-link')}</section><section class="panel"><span class="overline">READING GUIDE</span><h3>Start here</h3><ul class="reading-list">${s.readings.map(r=>`<li>${e(r)}</li>`).join('')}</ul><p class="fine">NTX = NeuroTechX (2021); RS = Royal Society (2019); MI = Milken Institute (2021). See the primer for source and pagination details.</p></section><section class="panel"><span class="overline">LEGAL CONNECTIONS</span>${s.lawIds.map(id=>{const law=DATA.laws.find(l=>l.id===id);return law?external(law.source,law.title,'resource'):'';}).join('')}</section></aside></div><div class="pagination">${button('session','← Previous',`data-id="${s.n-1}" ${s.n===1?'disabled':''}`)}<span class="fine">${s.n} / 14</span>${button('session','Next →',`data-id="${s.n+1}" ${s.n===14?'disabled':''}`)}</div>`;}
function primer() {return `${heading('A COMMON INTERDISCIPLINARY STARTING POINT','The participant primer','Learn the vocabulary. Understand the limits. Prepare for every session.',button('pdf','Download complete primer','data-key="primer"','button'))}<div class="primer-banner"><span class="overline">TWO PARTS. ONE CONNECTED LEARNING JOURNEY.</span><h2>From neural signals to legal questions.</h2><p>Part I introduces concepts, terminology and history.<br>Part II contains a preparatory module for each of the 14 sessions.</p></div><div class="toolbar"><div class="chips">${[['foundations','Foundations'],['glossary','Glossary · '+FOUNDATIONS.glossary.length],['history','Historical evolution'],['modules','Session modules'],['sources','Sources & use']].map(([v,label])=>`<button data-action="primer" data-value="${v}" aria-pressed="${state.primer===v}">${label}</button>`).join('')}</div></div>${primerBody()}`;}
function primerBody() {if(state.primer==='foundations')return FOUNDATIONS.modules.map((m,i)=>`<details class="foundation" ${i===0?'open':''}><summary><span class="number">0${i+1}</span><div><h3>${e(m.title)}</h3><p>${e(m.learning_goal)}</p></div></summary><div class="foundation-body prose">${paragraphs(m.paragraphs)}<div class="practice"><strong>Think it through</strong><p>${e(m.practice)}</p></div><details class="check"><summary>${e(m.check.question)}</summary><p>${e(m.check.answer)}</p></details><p class="fine">Read: ${e(m.reading.join('; '))}</p></div></details>`).join('');if(state.primer==='glossary')return `<input type="search" class="search wide" data-filter="glossary" placeholder="Search terms or definitions" aria-label="Search glossary" value="${e(state.glossary)}"><p class="fine">Introductory learning definitions, not statutory definitions or medical guidance.</p><div class="grid two" id="glossary-results">${glossaryResults()}</div>`;if(state.primer==='history')return `<p class="muted">A selective technical history drawn from the supplied 2019 and 2021 readings. Legal developments are recorded separately in the law tracker.</p><div class="timeline">${FOUNDATIONS.timeline.map(t=>`<article><span class="timeline-date">${e(t.date)}</span><div><h3>${e(t.title)}</h3><p>${e(t.text)}</p><span class="fine">${e(t.source)}</span></div></article>`).join('')}</div>`;if(state.primer==='modules')return `<div class="grid two">${DATA.sessions.map(sessionCard).join('')}</div>`;return `<div class="panel prose"><h2>Sources and editorial approach</h2><p>${e(FOUNDATIONS.editorial_note)}</p>${Object.entries(FOUNDATIONS.source_key).map(([key,value])=>`<h3>${e(key)}</h3><p>${e(value.citation)}</p><p class="fine">${e(value.pagination)}</p>`).join('')}<h3>Use the readings responsibly</h3><p>The older readings establish technical foundations; they do not establish current product approvals or the current state of the law. No source illustrations or substantial passages have been republished. Check primary sources before relying on a legal proposition.</p><h3>Learning method</h3>${list(FOUNDATIONS.how_to_use,true)}</div>`;}
function glossaryResults(){const rows=FOUNDATIONS.glossary.filter(g=>(g.term+' '+g.definition).toLowerCase().includes(state.glossary.toLowerCase()));return rows.length?rows.map(g=>`<article class="panel"><h3>${e(g.term)}</h3><p>${e(g.definition)}</p><span class="fine">${e(g.source)}</span></article>`).join(''):'<div class="empty">No matching terms. Try a shorter search.</div>';}
function tracker() {return `${heading('FROM LEGAL TEXT TO PRACTICAL RELEVANCE','Neurotechnology law tracker','A selected starting point for comparative legal research.',button('export-laws','Export reference data'))}<div class="toolbar"><div class="chips">${['Global','India'].map(r=>`<button data-action="region" data-value="${r}" aria-pressed="${state.region===r}">${r}</button>`).join('')}</div><span class="fine">Source collection checked 31 October 2026 · not a live update</span></div><div class="toolbar"><div class="chips">${[['Legislation','Acts & regulations'],['Judicial decisions','Judicial decisions'],['Policy frameworks','Policy frameworks']].map(([v,label])=>`<button data-action="law-type" data-value="${v}" aria-pressed="${state.lawType===v}">${label}</button>`).join('')}</div><input type="search" class="search" data-filter="lawSearch" placeholder="Search laws, cases or topics" aria-label="Search law tracker" value="${e(state.lawSearch)}"></div><div class="info">${state.lawType==='Policy frameworks'?'Recommendations and policy instruments are kept separate from binding legislation and court decisions.':'Research aids, not legal advice. Check scope, commencement, amendments and subsequent treatment in the primary sources.'}</div><div id="law-results">${lawResults()}</div><p class="fine">This is the source portal’s seed collection, not a live database export. No automatic monitoring or alerts are enabled.</p>`;}
function lawResults(){const rows=DATA.laws.filter(l=>l.region===state.region&&l.type===state.lawType&&JSON.stringify(l).toLowerCase().includes(state.lawSearch.toLowerCase())).sort((a,b)=>b.date.localeCompare(a.date));return rows.length?rows.map(l=>`<article class="law-card"><div><div class="law-meta"><span>${e(l.jurisdiction)}</span><span>${e(l.date)}</span></div><h2 class="law-title">${e(l.title)}</h2><p>${e(l.summary)}</p><div class="tags"><span class="tag">${e(l.status)}</span>${(l.tags||[]).map(t=>`<span class="tag">${e(t)}</span>`).join('')}</div><details class="scope"><summary>Scope and caution</summary><p>${e(l.caution)}</p><p class="fine">Source: ${e(l.sourceLabel)}</p></details></div><div class="law-actions">${external(l.source,'View primary source')}${l.secondarySource?external(l.secondarySource,'Explanatory note'):''}<span class="fine">Reviewed ${e(l.checked)}</span></div></article>`).join(''):'<div class="empty">No entries in this view. Try another category or search.</div>';}
function assignmentsBuilder() {return `${heading('CRITICAL THINKING INTO PRACTICE','Assignment drafts','Prepare a teaching task, save a local draft and export it.',button('export-drafts','Export all drafts'))}<div class="info">${e(DATA.course.assessment)}</div><div class="banner-small"><strong>Faculty workspace.</strong> Avoid personal or confidential information. ${persistence?'':'Storage is blocked: export your drafts before closing.'}</div><div class="section-heading"><h2>Create or edit a draft</h2><span class="fine">Not notified assessment instructions</span></div><div class="grid two"><section class="panel"><form id="assignment-form" class="assignment-form"><label>Title<input name="title" required maxlength="180" placeholder="e.g. A proportionate neurotechnology safeguard"></label><div class="form-row"><label>Task type<select name="type"><option>Reflective note</option><option>Case analysis</option><option>Policy brief</option><option>Short article</option><option>Other learning task</option></select></label><label>Session<select name="session"><option value="0">Course-wide</option>${DATA.sessions.map(s=>`<option value="${s.n}">${s.n}. ${e(s.title)}</option>`).join('')}</select></label></div><label>Instructions<textarea name="prompt" required maxlength="12000" rows="6" placeholder="Set the question, scope, sources and expected output."></textarea></label><div class="form-row"><label>Word guideline<input name="words" type="number" min="50" max="10000" value="1000" required></label><label>Maximum marks<input name="marks" type="number" min="1" max="1000" value="20" required></label></div><label>Proposed deadline (IST)<input name="deadline" type="datetime-local"></label><label>Rubric / marking guidance<textarea name="rubric" rows="3" maxlength="4000"></textarea></label><div class="actions"><button type="submit" class="button" id="save-draft">Save local draft</button>${button('reset-form','New draft','type="button"')}</div><p class="fine">Share finalised tasks with participants through the Google Form above.</p></form></section><section><div class="actions" style="margin-bottom:18px">${['Reflective note','Case analysis','Policy brief'].map(t=>button('template',e(t),`data-value="${t}"`,'button secondary small')).join('')}</div><div class="stack" id="draft-list">${draftList()}</div></section></div>`;}
function draftList() {return saved.assignments.length?saved.assignments.map(a=>`<article class="panel"><span class="pill">LOCAL DRAFT</span><h3 style="margin-top:15px">${e(a.title)}</h3><p class="prewrap">${e(a.prompt)}</p><p class="fine">${e(a.type)} · ${a.session?'Session '+e(a.session):'Course-wide'}<br>${e(a.words)} words · ${e(a.marks)} marks<br>${a.deadline?'Proposed deadline: '+e(a.deadline.replace('T',' '))+' IST':'No deadline set'}</p>${a.rubric?`<details class="scope"><summary>Rubric</summary><p class="prewrap">${e(a.rubric)}</p></details>`:''}<div class="actions" style="margin-top:16px">${button('edit-draft','Edit',`data-id="${e(a.id)}"`,'button secondary small')}${button('download-draft','Export text',`data-id="${e(a.id)}"`,'button secondary small')}${button('delete-draft','Delete',`data-id="${e(a.id)}"`,'button secondary small danger')}</div></article>`).join(''):'<div class="empty">No local drafts yet. Create one or begin with a template.</div>';}
function about() {return `${heading('COURSE INFORMATION','A shared space for learning.','',button('pdf','Download brochure','data-key="brochure"'))}<div class="about-grid"><img src="/api/asset/cover" alt="Mind, Machine & Justice, second edition course brochure cover"><div class="panel prose"><h2>About the course</h2><p>The School of Law, Forensic Justice &amp; Policy Studies, National Forensic Sciences University, in collaboration with the Centre for Neurotechnology &amp; Law, United Kingdom, is organising this seven-day online certificate course from 16–22 November 2026.</p><p>The course connects scientific literacy with the legal and ethical questions raised by neurotechnology. It welcomes participants from law, neuroscience, forensic science, medicine, technology, philosophy and public policy. Prior technical training in neuroscience is not required.</p><h3>Fee and dates</h3><p>Fee: ${e(DATA.course.fee)}, including course material and certificate.<br>Registration deadline: ${e(DATA.course.deadline)}.</p><h3>Assessment and certification</h3><p>${e(DATA.course.assessment)} Eligible participants receive a joint certificate from NFSU and CNL.</p><a href="mailto:${e(DATA.course.contact)}">${e(DATA.course.contact)}</a></div></div>`;}
function fillForm(values) {const form=document.getElementById('assignment-form');form.reset();for(const [key,value] of Object.entries(values)){const el=form.elements.namedItem(key);if(el&&'value'in el)el.value=String(value??'');}editId=values.id||null;document.getElementById('save-draft').textContent=editId?'Update local draft':'Save local draft';form.elements.title.focus();}
const TEMPLATES={'Reflective note':{title:'Course reflective note',type:'Reflective note',prompt:'Write a 1,000-word reflection connecting two course sessions. Explain one scientific limitation, compare two governance approaches and defend a practical safeguard for the Indian context. Cite your sources and distinguish existing law from proposals.',rubric:'Conceptual understanding: 5; critical comparison: 5; application and safeguards: 5; sources and clarity: 5.'},'Case analysis':{title:'Neural data and the courts',type:'Case analysis',prompt:'Analyse a judgment discussed in the course. Distinguish material facts, legal questions, reasoning and operative relief. Identify what the decision does and does not establish for neurotechnology governance.',rubric:'Accurate case analysis: 8; critical reasoning: 6; application and limitations: 4; sources and clarity: 2.'},'Policy brief':{title:'A proportionate neurotechnology safeguard',type:'Policy brief',prompt:'Develop a policy brief for one concrete neurotechnology use. Define the problem and affected group; identify applicable law and scientific uncertainty; propose three safeguards, responsible actors and a review mechanism.',rubric:'Problem and evidence: 5; legal analysis: 5; feasible safeguards: 7; sources and clarity: 3.'}};
document.addEventListener('click',event=>{const el=event.target.closest('[data-action]');if(!el||el.disabled)return;const action=el.dataset.action;const n=Number(el.dataset.id);if(action==='navigate')go(el.dataset.view);else if(action==='session'&&n>=1&&n<=14)go('sessions',n);else if(action==='day'){state.day=el.dataset.value;render();}else if(action==='primer'){state.primer=el.dataset.value;render();}else if(action==='region'){state.region=el.dataset.value;render();}else if(action==='law-type'){state.lawType=el.dataset.value;render();}else if(action==='calendar')calendar();else if(action==='calendar-one')calendar(DATA.sessions.filter(s=>s.n===n));else if(action==='pdf')downloadPDF(el.dataset.key);else if(action==='prepared'){saved.progress=saved.progress.includes(n)?saved.progress.filter(x=>x!==n):[...saved.progress,n];const ok=persist();render();if(ok)notice('Preparation progress saved locally. This is not attendance.');}else if(action==='export-laws')download('neurotechnology-law-tracker.json',JSON.stringify(DATA.laws,null,2),'application/json');else if(action==='export-drafts')download0('mmj-local-assignment-drafts.json',JSON.stringify({offline:true,exportedAt:new Date().toISOString(),assignments:saved.assignments},null,2),'application/json');else if(action==='template')fillForm({...TEMPLATES[el.dataset.value],session:0,words:1000,marks:20});else if(action==='reset-form')fillForm({words:1000,marks:20});else if(action==='edit-draft'){const a=saved.assignments.find(a=>a.id===el.dataset.id);if(a)fillForm(a);}else if(action==='delete-draft'){const a=saved.assignments.find(a=>a.id===el.dataset.id);if(a&&confirm('Delete this local draft? Export it first if you need a copy.')){saved.assignments=saved.assignments.filter(x=>x.id!==a.id);const ok=persist();if(editId===a.id)editId=null;render();if(ok)notice('Local draft deleted.');}}else if(action==='download-draft'){const a=saved.assignments.find(a=>a.id===el.dataset.id);if(a)download0('MMJ-Assignment-Draft.txt',`${a.title}\nLOCAL DRAFT — not published or submitted\n\nType: ${a.type}\nSession: ${a.session||'Course-wide'}\nWords: ${a.words}\nMarks: ${a.marks}\nProposed deadline (IST): ${a.deadline||'Not set'}\n\nInstructions\n${a.prompt}\n\nRubric\n${a.rubric||'Not set'}`);}});
document.addEventListener('input',event=>{const key=event.target.dataset.filter;if(!key)return;state[key]=event.target.value;const targets={search:['session-results',sessionResults],glossary:['glossary-results',glossaryResults],lawSearch:['law-results',lawResults],libSearch:['lib-results',libResults],libCat:['lib-results',libResults],pSearch:['p-results',partResults],pStatus:['p-results',partResults]};if(targets[key])document.getElementById(targets[key][0]).innerHTML=targets[key][1]();});
document.addEventListener('submit',event=>{if(event.target.id!=='assignment-form')return;event.preventDefault();const form=event.target;if(!form.reportValidity())return;const values=Object.fromEntries(new FormData(form));if(!values.title.trim()||!values.prompt.trim()){notice('Please enter a title and instructions.');return;}const a={id:editId||('draft-'+Date.now()+'-'+Math.random().toString(36).slice(2,8)),title:values.title.trim(),type:values.type,session:Number(values.session),prompt:values.prompt.trim(),words:Number(values.words),marks:Number(values.marks),deadline:values.deadline,rubric:values.rubric.trim(),updatedAt:new Date().toISOString()};const index=saved.assignments.findIndex(x=>x.id===a.id);if(index>=0)saved.assignments[index]=a;else saved.assignments.unshift(a);const ok=persist();editId=null;render();if(ok)notice('Draft saved in this browser only. It has not been published or submitted.');});
document.getElementById('menu').addEventListener('click',()=>{const open=document.getElementById('sidebar').classList.toggle('show');document.getElementById('menu').setAttribute('aria-expanded',String(open));});
document.addEventListener('keydown',event=>{if(event.key==='Escape'){document.getElementById('sidebar').classList.remove('show');document.getElementById('menu').setAttribute('aria-expanded','false');}});
function assignments(){const url=CFG.formUrl;const ok=safeURL(url)!=='#';const hero=`<section class="assign-hero"><div class="ah-grid"><div><span class="pill">✦ ASSIGNMENT DRAFTS</span><h2>Your ideas deserve a <em>beautiful stage.</em></h2><p class="ah-lead">Every landmark argument began as a rough draft. Think boldly, write fearlessly, back your claims with evidence, and when you are ready, submit with pride. We cannot wait to read what you create.</p><div class="ah-steps"><div><b>1</b>Read the session guides and note your questions</div><div><b>2</b>Draft your assignment with care and clarity</div><div><b>3</b>Submit it through the official Google Form</div></div></div><div class="ah-card"><div class="ic">✎</div><h3>Submit your assignment</h3><p>One official Google Form for Mind, Machine &amp; Justice. Quick, clean and secure.</p><div class="ah-lines"><i></i><i></i><i></i></div><a class="button" ${ok?`href="${e(safeURL(url))}" target="_blank" rel="noopener noreferrer"`:'aria-disabled="true"'}>${ok?'Open Google Form ↗':'Form opens soon ✦'}</a><p class="fine">${ok?'Opens in a new tab · sign in with your Google account if asked':'The organisers will publish the form link here.'}</p>${isAdmin()?`<form id="formurl-form"><span class="badge-admin" style="justify-self:start;margin:0">ADMIN ONLY</span><input name="url" type="url" placeholder="Paste Google Form link (https://…)" value="${e(url||'')}"><button class="button" type="submit">Save link</button></form>`:''}</div></div></section><div class="ah-note"><b>💡</b><div><strong>Assessment guide.</strong><p class="muted" style="margin:6px 0 0">${e(DATA.course.assessment)}</p></div></div>`;return isStaff()?hero+assignmentsBuilder():heading('CRITICAL THINKING INTO PRACTICE','Assignment drafts','Prepare your work and submit it with the Google Form.')+hero}

/* ======================= server-backed part ======================= */
const ROLE_LABEL={admin:'Admin',faculty:'Faculty',participant:'Participant'};
let user=null, FILES=[], CFG={categories:[],max_mb:50,overrides:{sessions:{}},links:{},formUrl:''};
const isAdmin=()=>user?.role==='admin', isStaff=()=>!!user&&user.role!=='participant';
const download=download0;
const $=id=>document.getElementById(id);
const api=(u,o={})=>fetch(u,{...o,headers:{'X-Requested-With':'fetch',...(o.json?{'Content-Type':'application/json'}:{}),...o.headers},body:o.json?JSON.stringify(o.json):o.body}).then(async r=>{const d=await r.json().catch(()=>({}));if(r.status===401){location='/login';throw 'Please sign in again'}if(!r.ok)throw d.error||'Something went wrong';return d});
const staffTabs=()=>isAdmin()?[['dashboard','Dashboard'],['participants','Participants'],['attendance','Attendance'],['report','Attendance report'],['upload','Upload & files'],['users','Users & IDs'],['activity','Activity log'],['branding','Logos & settings']]:isStaff()?[['attendance','Attendance'],['report','Attendance report'],['upload','Upload & files']]:[];
const allTabs=()=>[...MAIN_TABS,...staffTabs()];

function applyOverrides(){for(const s of DATA.sessions){if(!s._o)s._o={title:s.title,overview:s.overview};const o=(CFG.overrides.sessions||{})[s.n];s.title=(o&&o.title)||s._o.title;s.overview=(o&&o.overview)||s._o.overview;s.note=(o&&o.note)||''}}
function dlButtons(){return `<div class="actions">${button('pdf','Download participant primer','data-key="primer"')}${button('pdf','Download course brochure','data-key="brochure"')}</div>`}

/* ---- files ---- */
const ext=f=>(f.orig_name.split('.').pop()||'').toLowerCase();
const isVideo=f=>['mp4','webm','mov','m4v'].includes(ext(f)), isAudio=f=>['mp3','wav','m4a'].includes(ext(f)), isImage=f=>['png','jpg','jpeg','gif','webp'].includes(ext(f));
const canInline=f=>isVideo(f)||isAudio(f)||isImage(f)||ext(f)==='pdf';
const kb=n=>n>1048576?(n/1048576).toFixed(1)+' MB':Math.max(1,Math.round(n/1024))+' KB';
const canDel=f=>isAdmin()||(user.role==='faculty'&&f.uploaded_by===user.username);
function fileTable(rows,manage){return `<div class="table-wrap"><table class="tbl"><thead><tr><th>Title</th><th>Category</th><th>Session</th><th>Size</th><th>Added</th>${manage?'<th>By</th>':''}<th></th></tr></thead><tbody>${rows.map(f=>`<tr><td><b>${e(f.title)}</b><br><small>${e(f.orig_name)}</small></td><td>${e(f.category)}</td><td>${f.session_no?'Session '+f.session_no:'–'}</td><td>${kb(f.size)}</td><td>${e(String(f.created).slice(0,10))}</td>${manage?`<td>${e(f.uploaded_by)}</td>`:''}<td style="white-space:nowrap">${canInline(f)?`<a class="button secondary small" href="/api/files/${f.id}/view" target="_blank" rel="noopener">View</a> `:''}<a class="button small" href="/api/files/${f.id}/download">Download</a>${manage&&canDel(f)?` ${button('del-file','Delete',`data-id="${f.id}"`,'button secondary small danger')}`:''}</td></tr>`).join('')}</tbody></table></div>`}
function libResults(){const q=state.libSearch.toLowerCase(),c=state.libCat;const rows=FILES.filter(f=>(!c||f.category===c)&&(!q||(f.title+' '+f.orig_name).toLowerCase().includes(q)));return rows.length?fileTable(rows,false):'<div class="empty">No files yet. Materials appear here as the organisers upload them.</div>'}
function library(){state.libSearch=state.libSearch||'';state.libCat=state.libCat||'';return `${heading('COURSE FILES','Downloads','Brochure, primer, readings and session materials shared by the organisers.')}<div class="toolbar"><select class="search" data-filter="libCat" aria-label="Category"><option value="">All categories</option>${CFG.categories.map(c=>`<option ${state.libCat===c?'selected':''}>${e(c)}</option>`).join('')}</select><input class="search" type="search" data-filter="libSearch" placeholder="Search files" aria-label="Search files" value="${e(state.libSearch)}"></div><div id="lib-results">${libResults()}</div>`}

function uploadOne(file,meta,onProgress){return new Promise((res,rej)=>{const fd=new FormData();fd.append('file',file);fd.append('title',meta.title||file.name.replace(/\.[^.]+$/,''));fd.append('category',meta.category||'Other');if(meta.session)fd.append('session_no',meta.session);const x=new XMLHttpRequest();x.open('POST','/api/files');x.setRequestHeader('X-Requested-With','fetch');x.upload.onprogress=ev=>{if(ev.lengthComputable)onProgress(ev.loaded/ev.total)};x.onload=()=>{let d={};try{d=JSON.parse(x.responseText)}catch{}x.status<300?res(d):rej(d.error||'Upload failed ('+x.status+')')};x.onerror=()=>rej('Network error. Please try again.');x.send(fd)})}
async function uploadMany(files,meta,statusId){files=[...files];if(!files.length){notice('Choose at least one file.');return}
  const st=$(statusId);let ok=0,bad=[];
  for(const f of files){if(f.size>CFG.max_mb*1048576){bad.push(f.name+' is larger than '+CFG.max_mb+' MB (use a video link instead)');continue}
    if(st)st.innerHTML=`<div class="bar"><i id="barfill"></i></div><span class="fine">Uploading ${e(f.name)} (${files.indexOf(f)+1} of ${files.length})…</span>`;
    try{await uploadOne(f,{...meta,title:files.length===1?meta.title:''},p=>{const b=$('barfill');if(b)b.style.width=Math.round(p*100)+'%'});ok++}catch(err){bad.push(f.name+': '+err)}}
  try{FILES=await api('/api/files')}catch{}
  const sessionView=state.view==='sessions';render();
  notice((ok?ok+' file'+(ok>1?'s':'')+' uploaded. ':'')+(bad.length?'Problem: '+bad.join('; '):'Participants can see it now.'))}

/* ---- session page: media + staff tools ---- */
function mediaPanel(s){const items=FILES.filter(f=>f.session_no===s.n),links=(CFG.links[s.n]||[]),edit=state.editSession===s.n;
  const cards=items.map(f=>`<figure class="media">${isVideo(f)?`<video controls preload="metadata" src="/api/files/${f.id}/view"></video>`:isImage(f)?`<img loading="lazy" src="/api/files/${f.id}/view" alt="${e(f.title)}">`:isAudio(f)?`<div class="filebox"><audio controls preload="none" style="width:90%" src="/api/files/${f.id}/view"></audio></div>`:`<div class="filebox">📄</div>`}<figcaption><span>${e(f.title)}</span>${canInline(f)&&!isVideo(f)&&!isImage(f)&&!isAudio(f)?`<a class="text-link" href="/api/files/${f.id}/view" target="_blank" rel="noopener">Open</a>`:''}<a class="text-link" href="/api/files/${f.id}/download">Download</a>${canDel(f)?button('del-file','Delete',`data-id="${f.id}"`,'text-link'):''}</figcaption></figure>`).join('');
  const linkCards=links.map((l,i)=>`<div class="link-item"><div><strong>▶ ${e(l.label||'Recording')}</strong><span class="fine">${e(safeURL(l.url).replace(/^https:\/\//,'').slice(0,60))}</span></div><div class="actions" style="margin:0">${external(l.url,'Watch / open','button secondary small')}${isStaff()?button('del-link','Remove',`data-id="${s.n}" data-i="${i}"`,'text-link'):''}</div></div>`).join('');
  const box=isStaff()?`<div class="admin-box"><span class="badge-admin">${isAdmin()?'ADMIN ONLY':'FACULTY ONLY'}</span><h3>Manage Session ${String(s.n).padStart(2,'0')}</h3><p class="fine" style="margin:0 0 6px">Upload videos, photos or PDFs (up to ${CFG.max_mb} MB each) or add a link for long recordings. Changes are live for all participants immediately.</p><label class="upload"><input type="file" multiple accept="video/*,audio/*,image/*,.pdf,.doc,.docx,.ppt,.pptx,.xls,.xlsx,.zip" data-upload="${s.n}">⬆ Upload video / photos / files</label><div id="up-s${s.n}"></div><form id="link-form" class="assignment-form" data-id="${s.n}"><div class="form-row"><label>Video / folder link title<input name="label" placeholder="e.g. Day 1 · Session 1 recording" maxlength="120"></label><label>Link (https://…)<input name="url" type="url" required placeholder="YouTube, Google Drive, Vimeo…"></label></div><div class="actions"><button class="button secondary" type="submit">+ Add link</button></div></form>${isAdmin()?button('edit-session',edit?'Close editor':'✎ Edit session details',`data-id="${s.n}"`):''}${isAdmin()&&edit?`<form id="session-form" class="assignment-form" data-id="${s.n}" style="margin-top:16px"><label>Title<input name="title" value="${e(s.title)}" required></label><label>Overview<textarea name="overview" rows="5">${e(s.overview)}</textarea></label><label>Note for participants (shown above)<textarea name="note" rows="2">${e(s.note||'')}</textarea></label><div class="actions"><button class="button" type="submit">Save changes</button>${button('reset-session','Restore original',`data-id="${s.n}"`,'button secondary')}</div></form>`:''}</div>`:'';
  return `<section class="panel session-files"><span class="overline">SESSION MEDIA</span><h2>Recordings, photos &amp; files</h2>${s.note?`<div class="info">${e(s.note)}</div>`:''}${linkCards?`<div class="link-list">${linkCards}</div>`:''}${items.length?`<div class="media-grid">${cards}</div>`:(linkCards?'':'<div class="empty">Nothing uploaded for this session yet.</div>')}${box}</section>`}
function sessionDetail(s){return sessionDetailBase(s).replace('</div><aside class="stack detail-aside">',mediaPanel(s)+'</div><aside class="stack detail-aside">')}

/* ---- staff: upload & files ---- */
function sessionOptions(blank){return `<option value="">${blank}</option>`+DATA.sessions.map(s=>`<option value="${s.n}">Session ${s.n} · ${e(s.title.slice(0,50))}</option>`).join('')}
function upload(){const mine=isAdmin()?FILES:FILES;return `${heading(isAdmin()?'ADMIN · COURSE FILES':'FACULTY · COURSE FILES','Upload & files','Add videos, photos, PDFs and other materials. Participants see them as soon as they are uploaded.')}
<div class="grid two"><section class="panel"><h2>Upload files</h2><form id="upload-form" class="assignment-form"><label>Title <span class="fine">(optional · file name is used if empty)</span><input name="title" maxlength="160" placeholder="e.g. Session 3 slides"></label><div class="form-row"><label>Category<select name="category">${CFG.categories.map(c=>`<option ${c==='Session Materials'?'selected':''}>${e(c)}</option>`).join('')}</select></label><label>Session <span class="fine">(optional)</span><select name="session">${sessionOptions('Not linked to a session')}</select></label></div><label class="upload"><input type="file" id="up-input" multiple accept="video/*,audio/*,image/*,.pdf,.doc,.docx,.ppt,.pptx,.xls,.xlsx,.txt,.csv,.zip">⬆ Choose files or drop them here<small>PDF, Word, PowerPoint, Excel, ZIP, MP4/MP3, images · max ${CFG.max_mb} MB each</small></label><div class="picked" id="picked"></div><div id="up-main"></div><div class="actions"><button class="button" type="submit">Upload</button></div></form></section>
<section class="panel"><h2>Add a video link</h2><p class="muted" style="font-size:13px">For long recordings use YouTube, Vimeo or Google Drive and paste the link. It shows on that session’s page.</p><form id="link-form" class="assignment-form"><label>Session<select name="session" required>${sessionOptions('Choose a session').replace('<option value="">Choose a session</option>','<option value="" disabled selected>Choose a session</option>')}</select></label><label>Link title<input name="label" maxlength="120" placeholder="e.g. Day 1 · Session 1 recording"></label><label>Link (https://…)<input name="url" type="url" required placeholder="https://…"></label><div class="actions"><button class="button secondary" type="submit">+ Add link</button></div></form></section></div>
<div class="section-heading"><div><span class="overline">ALL MATERIALS</span><h2>${FILES.length} file${FILES.length===1?'':'s'}</h2></div></div>${FILES.length?fileTable(FILES,true):'<div class="empty">Nothing uploaded yet.</div>'}${isAdmin()?'':'<p class="fine" style="margin-top:12px">Faculty can delete only their own uploads.</p>'}`}

/* ---- admin: users / activity / branding ---- */
function users(){return `${heading('ADMIN · ACCESS','Users & IDs','Create sign-in IDs for admin, law faculty and participants. Share the participant ID with everyone enrolled; set a new password if it leaks.')}<section class="panel" style="margin-bottom:22px"><h2>Create a new ID</h2><form id="user-form" class="assignment-form"><div class="form-row"><label>Username<input name="username" required placeholder="e.g. faculty2" autocapitalize="none"></label><label>Display name<input name="name" placeholder="e.g. Dr. Sharma"></label></div><div class="form-row"><label>Role<select name="role"><option value="faculty">Law faculty (upload + attendance)</option><option value="admin">Admin (everything)</option><option value="participant">Participant (read the course)</option></select></label><label>Password <span class="fine">(blank = auto-generate)</span><input name="password" placeholder="min 8 characters"></label></div><div class="actions"><button class="button" type="submit">Create ID</button></div></form><div id="newid"></div></section><div id="pane-body"><div class="empty">Loading…</div></div><p class="fine" style="margin-top:12px">Use the backup participant ID to switch over quickly.</p>`}
async function loadUsers(){const u=await api('/api/admin/users');$('pane-body').innerHTML=`<div class="table-wrap"><table class="tbl"><thead><tr><th>ID</th><th>Role</th><th>Name</th><th>Status</th><th>New password</th><th></th></tr></thead><tbody>${u.map(x=>`<tr><td><b>${e(x.username)}</b></td><td>${e(x.role)}</td><td>${e(x.name)}</td><td><span class="${x.active?'on-pill':'off-pill'}">${x.active?'Active':'Disabled'}</span></td><td><input type="text" id="pw${x.id}" placeholder="min 8 characters" style="min-width:170px;padding:9px;border:1px solid #cad7e4;border-radius:7px"></td><td style="white-space:nowrap">${button('del-user','Delete',`data-id="${x.id}"`,'button danger small')} ${button('set-pw','Save',`data-id="${x.id}"`,'button small')} ${button('tog-user',x.active?'Disable':'Enable',`data-id="${x.id}" data-on="${x.active?0:1}"`,'button secondary small')}</td></tr>`).join('')}</tbody></table></div>`}
function activity(){return `${heading('ADMIN · ACTIVITY','Activity log','Recent sign-ins, downloads and uploads.')}<div id="pane-body"><div class="empty">Loading…</div></div>`}
async function loadLogs(){const d=await api('/api/admin/logs');const failed=d.logs.filter(l=>l.action==='login_failed').length;$('pane-body').innerHTML=`<div class="stats">${[['Files',d.stats.files],['Downloads',d.stats.downloads],['Logins',d.stats.logins],['Failed (recent)',failed]].map(([a,b],i)=>`<div class="stat"><span>0${i+1} / ${a.toUpperCase()}</span><strong>${b}</strong></div>`).join('')}</div><div class="table-wrap"><table class="tbl"><thead><tr><th>Time</th><th>User</th><th>Action</th><th>Detail</th><th>IP</th></tr></thead><tbody>${d.logs.map(l=>`<tr><td style="white-space:nowrap">${e(l.ts)}</td><td>${e(l.username)}</td><td>${e(l.action)}</td><td>${e(l.detail)}</td><td>${e(l.ip)}</td></tr>`).join('')}</tbody></table></div>`}
function branding(){const v=Date.now();return `${heading('ADMIN · SETTINGS','Logos & settings','Change the two logos, their size and the Google Form link for assignments.')}<div class="grid three">${[0,1].map(n=>`<section class="panel"><h3 style="margin-top:0">${n?'Logo 2 (right · CNL)':'Logo 1 (left · NFSU)'}</h3><img class="logo-prev" id="l${n}" src="/logo/${n}?t=${v}" alt=""><br><input type="file" id="f${n}" accept="image/png,image/jpeg,image/webp"><div class="actions" style="margin-top:12px">${button('up-logo','Upload',`data-n="${n}"`,'button small')}${button('reset-logo','Reset',`data-n="${n}"`,'button secondary small')}</div></section>`).join('')}<section class="panel"><h3 style="margin-top:0">Logo size</h3><input type="range" id="sz" min="36" max="110" step="2" value="70"><p><b id="szv">70 px</b></p>${button('save-size','Save size','','button small')}</section></div><section class="panel" style="margin-top:18px"><h3 style="margin-top:0">Assignment Google Form link</h3><form id="formurl-form" class="assignment-form"><input name="url" type="url" placeholder="https://forms.gle/…" value="${e(CFG.formUrl||'')}"><div class="actions"><button class="button" type="submit">Save link</button></div></form></section><p class="fine" style="margin-top:12px">PNG, JPG or WEBP. Logo changes show everywhere after a refresh.</p>`}
async function loadBrand(){try{const b=await api('/api/admin/branding');$('sz').value=b.size;$('szv').textContent=b.size+' px'}catch{}}


/* ---- admin: participants ---- */
let PART=[], PENDING=0, CREDS=null;
const csvCell=v=>'"'+String(v??'').replace(/"/g,'""')+'"';
function statusPill(st){return st==='approved'?'<span class="on-pill">Approved</span>':st==='pending'?'<span class="warn-pill">Pending</span>':'<span class="off-pill">Rejected</span>'}
function partResults(){const q=(state.pSearch||'').toLowerCase(),st=state.pStatus||'';const rows=PART.filter(p=>(!st||p.status===st)&&(!q||[p.name,p.email,p.phone,p.org,p.ref,p.username].join(' ').toLowerCase().includes(q)));
  if(!rows.length)return '<div class="empty">No participants match. Sign-up requests and added participants appear here.</div>';
  return `<div class="table-wrap"><table class="tbl"><thead><tr><th>Participant</th><th>Phone</th><th>Organisation</th><th>Payment ref</th><th>Requested</th><th>Status</th><th>Login ID</th><th>Logins</th><th>Last login</th><th>Downloads</th><th></th></tr></thead><tbody>${rows.map(p=>`<tr><td><b>${e(p.name)}</b><br><small>${e(p.email)}</small></td><td>${e(p.phone||'–')}</td><td>${e(p.org||'–')}</td><td>${e(p.ref||'–')}</td><td style="white-space:nowrap">${e(String(p.created).slice(0,10))}</td><td>${statusPill(p.status)}</td><td>${p.username?`<code>${e(p.username)}</code>`:'–'}</td><td>${p.logins}</td><td style="white-space:nowrap">${e(p.last_login?String(p.last_login).slice(0,16):'–')}</td><td>${p.downloads}</td><td style="white-space:nowrap">${p.status==='pending'?button('p-approve','Approve',`data-id="${p.id}"`,'button small')+' ':''}${p.username?button('p-reset','New password',`data-id="${p.id}"`,'button secondary small')+' ':''}${p.status!=='rejected'?button('p-reject','Reject',`data-id="${p.id}"`,'button secondary small danger')+' ':''}${button('p-del','Delete',`data-id="${p.id}"`,'button secondary small danger')}</td></tr>`).join('')}</tbody></table></div>`}
function credsBox(){if(!CREDS)return '';const c=CREDS;const body=`Hello ${c.name},\n\nYour Mind, Machine & Justice portal login:\nUser ID: ${c.username}\nPassword: ${c.password}\n\nSign in at ${location.origin}/login`;
  return `<div class="creds"><span class="badge-admin">LOGIN READY · SHOWN ONCE</span><h3 style="margin:4px 0 8px">${e(c.name)}</h3><p style="margin:0 0 12px">User ID <code>${e(c.username)}</code> &nbsp; Password <code>${e(c.password)}</code></p><div class="actions"><button class="button small" data-action="p-copy">Copy login details</button><a class="button secondary small" href="mailto:${e(c.email||'')}?subject=${encodeURIComponent('Your Mind, Machine & Justice portal login')}&body=${encodeURIComponent(body)}">Email it</a><button class="button secondary small" data-action="p-dismiss">Done</button></div><p class="fine" style="margin-top:10px">The password cannot be shown again. Use “New password” if it is lost.</p></div>`}
function participants(){const t=PART.length,a=PART.filter(p=>p.status==='approved').length,pe=PART.filter(p=>p.status==='pending').length;
  return `${heading('ADMIN · PARTICIPANTS','Participants','Everyone who requested or received access, with payment reference and activity.',button('p-csv','⬇ Export CSV','','button secondary'))}<div id="creds">${credsBox()}</div><div class="stats">${[['Total',t],['Approved',a],['Pending',pe],['Rejected',t-a-pe]].map(([l,n],i)=>`<div class="stat"><span>0${i+1} / ${l.toUpperCase()}</span><strong>${n}</strong></div>`).join('')}</div>
<details class="foundation" style="margin-bottom:18px"><summary><div><h3>Add a participant manually</h3><p>Creates a personal login straight away.</p></div></summary><div class="foundation-body"><form id="p-add" class="assignment-form" style="margin-top:20px"><div class="form-row"><label>Full name<input name="name" required maxlength="120"></label><label>Email<input name="email" type="email" required></label></div><div class="form-row3"><label>Phone<input name="phone" maxlength="30"></label><label>Organisation<input name="org" maxlength="160"></label><label>Payment reference<input name="ref" maxlength="120"></label></div><div class="actions"><button class="button" type="submit">Add &amp; create login</button></div></form></div></details>
<div class="toolbar"><div class="chips"><select class="search" data-filter="pStatus" aria-label="Status"><option value="">All statuses</option><option value="pending">Pending</option><option value="approved">Approved</option><option value="rejected">Rejected</option></select></div><input class="search" type="search" data-filter="pSearch" placeholder="Search name, email, payment ref…" aria-label="Search participants"></div><div id="p-results"><div class="empty">Loading…</div></div><p class="fine" style="margin-top:12px">The shared IDs (participant, participant2) are managed under “Users &amp; passwords”.</p>`}
async function loadParts(){PART=await api('/api/admin/participants');PENDING=PART.filter(p=>p.status==='pending').length;const el=$('p-results');if(el)el.innerHTML=partResults();document.querySelectorAll('.stats .stat strong').forEach(()=>{});const nav=document.querySelector('[data-view="participants"]');if(nav){nav.querySelector('.nav-count')?.remove();if(PENDING)nav.insertAdjacentHTML('beforeend',`<span class="nav-count">${PENDING}</span>`)}
  const t=PART.length,a=PART.filter(p=>p.status==='approved').length;const vals=[t,a,PENDING,t-a-PENDING];document.querySelectorAll('#main .stats .stat strong').forEach((n,i)=>n.textContent=vals[i])}
async function partAct(label,fn){try{const r=await fn();return r}catch(err){notice(String(err))}}
document.addEventListener('click',async ev=>{const el=ev.target.closest('[data-action]');if(!el||!isAdmin())return;const a=el.dataset.action,id=el.dataset.id;
  const show=(r,p)=>{CREDS={name:p.name,email:p.email,username:r.username,password:r.password};$('creds').innerHTML=credsBox();scrollTo(0,0)};
  try{
  if(a==='p-approve'){const p=PART.find(x=>x.id==id);const r=await api(`/api/admin/participants/${id}/approve`,{method:'POST'});await loadParts();show(r,p)}
  else if(a==='p-reset'){const p=PART.find(x=>x.id==id);if(!confirm('Set a new password for '+p.name+'? The old one stops working.'))return;const r=await api(`/api/admin/participants/${id}/reset`,{method:'POST'});await loadParts();show(r,p)}
  else if(a==='p-reject'){const p=PART.find(x=>x.id==id);if(!confirm('Reject '+p.name+'? Their login (if any) will be disabled.'))return;await api(`/api/admin/participants/${id}/reject`,{method:'POST'});await loadParts();notice('Rejected.')}
  else if(a==='p-del'){const p=PART.find(x=>x.id==id);if(!confirm('Delete '+p.name+' permanently, including their login?'))return;await api('/api/admin/participants/'+id,{method:'DELETE'});await loadParts();notice('Deleted.')}
  else if(a==='p-dismiss'){CREDS=null;$('creds').innerHTML=''}
  else if(a==='p-copy'){const c=CREDS;await navigator.clipboard.writeText(`User ID: ${c.username}\nPassword: ${c.password}\n${location.origin}/login`);notice('Login details copied.')}
  else if(a==='p-csv'){const head=['Name','Email','Phone','Organisation','Payment ref','Requested','Status','Login ID','Logins','Last login','Downloads'];const rows=PART.map(p=>[p.name,p.email,p.phone,p.org,p.ref,p.created,p.status,p.username,p.logins,p.last_login,p.downloads]);download0('participants.csv','\ufeff'+[head,...rows].map(r=>r.map(csvCell).join(',')).join('\r\n'),'text/csv;charset=utf-8')}
  }catch(err){notice(String(err))}});
document.addEventListener('submit',async ev=>{if(ev.target.id!=='p-add'||!isAdmin())return;ev.preventDefault();const f=ev.target,d=Object.fromEntries(new FormData(f));
  try{const r=await api('/api/admin/participants',{method:'POST',json:d});f.reset();await loadParts();CREDS={name:d.name,email:d.email,username:r.username,password:r.password};$('creds').innerHTML=credsBox()}catch(err){notice(String(err))}});

const VIEWS={dashboard,attendance,report,checkin,participants,overview,sessions,primer,tracker,assignments,library,about,upload,users,activity,branding};
function render(){const tabs=allTabs(),st=staffTabs();
  $('userchip').innerHTML=`<span class="who">${e(user.name)} · ${ROLE_LABEL[user.role]}</span>${button('logout','Sign out','','button secondary small')}`;
  const mk=(t,i)=>`<button data-action="navigate" data-view="${t[0]}" ${state.view===t[0]?'aria-current="page"':''}><span class="nav-num">${String(i+1).padStart(2,'0')}</span>${t[1]}${t[0]==='sessions'?'<span class="nav-count">14</span>':''}${t[0]==='participants'&&PENDING?`<span class="nav-count">${PENDING}</span>`:''}</button>`;
  $('navigation').innerHTML=MAIN_TABS.map(mk).join('')+(st.length?`<div class="nav-group admin">${isAdmin()?'ADMIN':'FACULTY'}</div>`+st.map((t,i)=>mk(t,MAIN_TABS.length+i)).join(''):'');
  $('breadcrumb').textContent='COURSE WORKSPACE / '+(tabs.find(t=>t[0]===state.view)?.[1]||'Overview').toUpperCase();
  $('main').innerHTML=(VIEWS[state.view]||overview)();
  if(state.view==='participants')loadParts().catch(x=>notice(String(x)));if(state.view==='users')loadUsers().catch(x=>notice(String(x)));if(state.view==='activity')loadLogs().catch(x=>notice(String(x)));if(state.view==='branding')loadBrand();if(state.view==='dashboard')loadDash().catch(x=>notice(String(x)));if(state.view==='attendance')loadAtt().catch(x=>notice(String(x)));if(state.view==='report')loadRep().catch(x=>notice(String(x)));}

/* ---- actions ---- */
const SEL=(el,name)=>el.dataset[name];
document.addEventListener('click',async ev=>{const el=ev.target.closest('[data-action]');if(!el)return;const a=el.dataset.action;
  try{
  if(a==='logout'){await api('/api/logout',{method:'POST'});location='/login'}
  else if(a==='edit-session'&&isAdmin()){state.editSession=state.editSession===Number(el.dataset.id)?null:Number(el.dataset.id);render()}
  else if(a==='reset-session'&&isAdmin()){if(!confirm('Restore the original text of this session?'))return;await api('/api/admin/session/'+el.dataset.id,{method:'DELETE'});CFG.overrides=(await api('/api/settings')).overrides;applyOverrides();state.editSession=null;render();notice('Original text restored.')}
  else if(a==='del-link'&&isStaff()){if(!confirm('Remove this link?'))return;await api(`/api/session/${el.dataset.id}/links/${el.dataset.i}`,{method:'DELETE'});CFG.links=(await api('/api/settings')).links;render();notice('Link removed.')}
  else if(a==='del-file'){const f=FILES.find(x=>x.id===Number(el.dataset.id));if(!f||!confirm('Delete “'+f.title+'” permanently?'))return;await api('/api/files/'+f.id,{method:'DELETE'});FILES=await api('/api/files');render();notice('File deleted.')}
  else if(a==='set-pw'){const id=el.dataset.id,box=$('pw'+id);await api(`/api/admin/users/${id}/password`,{method:'POST',json:{password:box.value}});box.value='';notice('Password updated.')}
  else if(a==='tog-user'){await api(`/api/admin/users/${el.dataset.id}/active`,{method:'POST',json:{active:el.dataset.on==='1'}});loadUsers()}
  else if(a==='up-logo'){const n=el.dataset.n,f=$('f'+n).files[0];if(!f){notice('Choose an image first.');return}const fd=new FormData();fd.append('file',f);await api('/api/admin/logo/'+n,{method:'POST',body:fd});refreshLogo(n);notice('Logo updated.')}
  else if(a==='reset-logo'){await api('/api/admin/logo/'+el.dataset.n,{method:'DELETE'});refreshLogo(el.dataset.n);notice('Logo reset to the original.')}
  else if(a==='save-size'){const v=Number($('sz').value);await api('/api/admin/branding',{method:'POST',json:{size:v}});document.body.style.setProperty('--logo',v+'px');notice('Logo size saved.')}
  }catch(err){notice(String(err))}});
function refreshLogo(n){const t=Date.now();const p=$('l'+n);if(p)p.src='/logo/'+n+'?t='+t;const t1=document.querySelector(n==0?'.logo-left img':'.logo-cnl');if(t1)t1.src='/logo/'+n+'?t='+t}
document.addEventListener('input',ev=>{if(ev.target.id==='sz')$('szv').textContent=ev.target.value+' px'});
document.addEventListener('change',ev=>{const t=ev.target;
  if(t.matches('[data-upload]')&&isStaff()){const n=Number(t.dataset.upload);const files=[...t.files];const vid=files.every(f=>/^(video|audio)\//.test(f.type));uploadMany(files,{session:n,category:vid?'Recordings':'Session Materials'},'up-s'+n)}
  else if(t.id==='up-input'){$('picked').textContent=[...t.files].map(f=>f.name+' ('+kb(f.size)+')').join(' · ')}});
document.addEventListener('dragover',ev=>{if(ev.target.closest&&ev.target.closest('.upload')){ev.preventDefault();ev.target.closest('.upload').classList.add('drag')}});
document.addEventListener('dragleave',ev=>{ev.target.closest&&ev.target.closest('.upload')?.classList.remove('drag')});
document.addEventListener('drop',ev=>{const z=ev.target.closest&&ev.target.closest('.upload');if(!z)return;ev.preventDefault();z.classList.remove('drag');const inp=z.querySelector('input[type=file]');if(inp&&ev.dataTransfer.files.length){inp.files=ev.dataTransfer.files;inp.dispatchEvent(new Event('change',{bubbles:true}))}});
document.addEventListener('submit',async ev=>{const f=ev.target;
  try{
  if(f.id==='upload-form'&&isStaff()){ev.preventDefault();const files=$('up-input').files;const d=Object.fromEntries(new FormData(f));await uploadMany(files,{title:(d.title||'').trim(),category:d.category,session:d.session},'up-main')}
  else if(f.id==='link-form'&&isStaff()){ev.preventDefault();const n=f.dataset.id||f.session.value;if(!n){notice('Choose a session.');return}await api(`/api/session/${n}/links`,{method:'POST',json:{label:f.label.value,url:f.url.value.trim()}});CFG.links=(await api('/api/settings')).links;render();notice('Link added for Session '+n+'.')}
  else if(f.id==='session-form'&&isAdmin()){ev.preventDefault();const n=f.dataset.id,d=Object.fromEntries(new FormData(f));await api('/api/admin/session/'+n,{method:'POST',json:d});CFG.overrides=(await api('/api/settings')).overrides;applyOverrides();state.editSession=null;render();notice('Session updated.')}
  else if(f.id==='formurl-form'&&isAdmin()){ev.preventDefault();const u=f.url.value.trim();await api('/api/admin/formurl',{method:'POST',json:{url:u}});CFG.formUrl=u;render();notice('Google Form link saved.')}
  }catch(err){notice(String(err))}});


/* ---- dashboard, attendance, check-in, AI (added) ---- */
const today=()=>{const d=new Date();return new Date(d-d.getTimezoneOffset()*6e4).toISOString().slice(0,10)};
let attDay=today(),ATT=null,REP=null;
function dashboard(){return `${heading('ADMIN · LIVE NUMBERS','Dashboard','Visitors, sign-ups and attendance for the course website.')}<div id="pane-body"><div class="empty">Loading…</div></div>`}
async function loadDash(){const d=await api('/api/admin/overview'),mx=Math.max(1,...d.series.map(x=>x.visitors));
  const st=a=>`<div class="stats">${a.map(([k,v],i)=>`<div class="stat"><span>${k.toUpperCase()}</span><strong>${v}</strong></div>`).join('')}</div>`;
  $('pane-body').innerHTML=st([['Visitors today',d.visitors_today],['Total visitors',d.visitors_total],['Page views',d.pageviews],['Logins today',d.logins_today]])+st([['Sign-ups',d.signups],['Pending approval',d.pending],['Approved participants',d.approved],['Average attendance',d.attendance_rate+'%']])+`<section class="panel"><h2>Unique visitors per day</h2><div class="bar">${d.series.map(x=>`<div style="height:${x.visitors/mx*100}%"><span>${x.visitors}</span><small>${e(x.day.slice(5))}</small></div>`).join('')||'<p class="muted">No visits yet.</p>'}</div></section>`}
function attendance(){return `${heading(isAdmin()?'ADMIN · ATTENDANCE':'FACULTY · ATTENDANCE','Daily attendance','Mark students present or absent, or open self check-in so they can mark themselves.')}<div id="pane-body"><div class="empty">Loading…</div></div>`}
async function loadAtt(){const d=ATT=await api('/api/attendance?day='+attDay);
  $('pane-body').innerHTML=`<section class="panel" style="margin-bottom:18px"><div class="actions"><label class="fine" style="display:flex;gap:8px;align-items:center">Date <input type="date" id="att-day" value="${e(attDay)}" style="padding:9px;border:1px solid #cad7e4;border-radius:7px"></label><button class="button" data-action="att-save">Save attendance</button><button class="button secondary" data-action="att-all">Mark all present</button><button class="button secondary" data-action="att-code" data-open="${d.code?0:1}">${d.code?'Close':'Open'} self check-in</button></div>${d.code?`<div class="info">Self check-in is <b>open</b>. Code: <b style="font-size:24px;letter-spacing:4px">${e(d.code)}</b><br>Students open <b>Mark attendance</b> in their portal and enter their registered email and this code.</div>`:''}</section>
  <div class="table-wrap"><table class="tbl"><thead><tr><th>#</th><th>Name</th><th>Email</th><th>Attendance</th></tr></thead><tbody>${d.rows.map((r,i)=>`<tr><td>${i+1}</td><td><b>${e(r.name)}</b></td><td>${e(r.email)}</td><td><div class="actions" data-pid="${r.id}"><button class="button small ${r.status==='present'?'on':'secondary'}" data-action="att-mark" data-s="present">Present</button><button class="button small ${r.status==='absent'?'on a':'secondary'}" data-action="att-mark" data-s="absent">Absent</button>${r.via==='self'?'<span class="fine">self check-in</span>':''}</div></td></tr>`).join('')||'<tr><td colspan="4" class="muted">No approved participants yet. Approve sign-ups or bulk-add students first.</td></tr>'}</tbody></table></div>`}
function report(){return `${heading(isAdmin()?'ADMIN · ATTENDANCE':'FACULTY · ATTENDANCE','Attendance report','Days present for every approved participant.','<button class="button secondary" data-action="rep-csv">Export CSV</button>')}<div id="pane-body"><div class="empty">Loading…</div></div>`}
async function loadRep(){const d=REP=await api('/api/attendance/report');$('pane-body').innerHTML=`<p class="muted">${d.days.length} class day${d.days.length===1?'':'s'} recorded</p><div class="table-wrap"><table class="tbl"><thead><tr><th>Name</th><th>Email</th><th>Present</th>${d.days.map(x=>`<th>${e(x.slice(5))}</th>`).join('')}</tr></thead><tbody>${d.rows.map(r=>`<tr><td><b>${e(r.name)}</b></td><td>${e(r.email)}</td><td><b>${r.present}/${d.days.length}</b></td>${d.days.map(x=>`<td>${r.marks[x]?'✓':'–'}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}
function checkin(){return `${heading('DAILY ATTENDANCE','Mark attendance','Enter your registered email and the 4-digit code your faculty shows in class.')}<section class="panel" style="max-width:520px"><form id="checkin-form" class="assignment-form"><label>Registered email<input name="email" type="email" required placeholder="you@example.com"></label><label>Today's code<input name="code" inputmode="numeric" maxlength="4" required placeholder="0000"></label><button class="button" type="submit">Mark me present</button><p class="fine" id="ci-msg"></p></form></section>`}
document.addEventListener('click',async ev=>{const el=ev.target.closest('[data-action]');if(!el)return;const a=el.dataset.action;
  try{
  if(a==='att-mark'){const c=el.parentElement;c.querySelectorAll('button').forEach(b=>b.className='button small secondary');el.className='button small on'+(el.dataset.s==='absent'?' a':'')}
  else if(a==='att-all'){document.querySelectorAll('[data-pid]').forEach(c=>{c.querySelectorAll('button').forEach(b=>b.className='button small secondary');c.querySelector('button').className='button small on'})}
  else if(a==='att-save'){const marks={};document.querySelectorAll('[data-pid]').forEach(c=>{const on=c.querySelector('button.on');if(on)marks[c.dataset.pid]=on.dataset.s});await api('/api/attendance',{method:'POST',json:{day:attDay,marks}});notice('Attendance saved.')}
  else if(a==='att-code'){await api('/api/attendance/checkin_code',{method:'POST',json:{day:attDay,open:el.dataset.open==='1'}});loadAtt()}
  else if(a==='rep-csv'){const d=REP;download0('attendance.csv','\ufeff'+[['Name','Email','Days present',...d.days],...d.rows.map(r=>[r.name,r.email,r.present,...d.days.map(x=>r.marks[x]?'P':'A')])].map(r=>r.map(csvCell).join(',')).join('\r\n'),'text/csv;charset=utf-8')}
  else if(a==='del-user'&&isAdmin()){if(!confirm('Delete this ID permanently?'))return;await api('/api/admin/users/'+el.dataset.id,{method:'DELETE'});loadUsers();notice('ID deleted.')}
  }catch(err){notice(String(err))}});
document.addEventListener('change',ev=>{if(ev.target.id==='att-day'){attDay=ev.target.value||today();loadAtt().catch(x=>notice(String(x)))}});
document.addEventListener('submit',async ev=>{const f=ev.target;
  try{
  if(f.id==='user-form'&&isAdmin()){ev.preventDefault();const r=await api('/api/admin/users',{method:'POST',json:Object.fromEntries(new FormData(f))});f.reset();$('newid').innerHTML=`<div class="info" style="margin-top:16px">New ID created. Copy it now, the password is not shown again:<br><b>User ID:</b> ${e(r.username)} &nbsp; <b>Password:</b> ${e(r.password)}</div>`;loadUsers()}
  else if(f.id==='checkin-form'){ev.preventDefault();const m=$('ci-msg');try{const r=await api('/api/checkin',{method:'POST',json:Object.fromEntries(new FormData(f))});m.style.color='#1b7a43';m.textContent='Thank you, '+r.name+'. You are marked present.';f.reset()}catch(err){m.style.color='#b3372f';m.textContent=String(err)}}
  }catch(err){notice(String(err))}});

(async function boot(){
  try{const me=await api('/api/me');if(!me.user){location='/login';return}
    user=me.user;if(!isStaff())MAIN_TABS.push(['checkin','Mark attendance']);CFG.categories=me.categories;CFG.max_mb=me.max_mb;
    const [c,fd,st,files]=await Promise.all([api('/api/content'),api('/api/foundation'),api('/api/settings'),api('/api/files')]);
    DATA=c;FOUNDATIONS=fd;Object.assign(CFG,st);FILES=files;applyOverrides();if(isAdmin()){try{PART=await api('/api/admin/participants');PENDING=PART.filter(p=>p.status==='pending').length}catch{}}
    window.addEventListener('hashchange',readHash);readHash()}
  catch(err){$('main').innerHTML=`<div class="empty">Could not load the portal. ${e(err)}</div>`}
})();
